import{_ as i,o as t,c as o,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph Code Walkthrough: LibRBD I/O Flow Pt. 1 2020-10-27","description":"","frontmatter":{"title":"Ceph Code Walkthrough: LibRBD I/O Flow Pt. 1 2020-10-27","date":"2020-10-27T00:00:00.000Z","updated":"2020-11-03T00:00:00.000Z","tags":["Ceph","LibRBD","I/O流程","分布式存储","Ceph存储集群"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Code_Walkthrough_-_LibRBD_I_O_Flow_Pt._1_2020-10-27.md","filePath":"posts/2020/Ceph_Code_Walkthrough_-_LibRBD_I_O_Flow_Pt._1_2020-10-27.md","lastUpdated":1780460162000}'),_={name:"posts/2020/Ceph_Code_Walkthrough_-_LibRBD_I_O_Flow_Pt._1_2020-10-27.md"};function r(s,l,p,a,n,d){return t(),o("div",null,[...l[0]||(l[0]=[e('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> Ceph 中 RADOS 块设备 (RBD) 的 I/O 路径分析</p><p><strong>主讲人：</strong> Jason Dillman</p><p><strong>会议内容总结：</strong></p><ol><li><p><strong>介绍与目标：</strong></p><ul><li>Jason Dillman 是 Ceph 项目中 RADOS 块设备 (RBD) 部分的 Tech Lead。</li><li>会议目标是详细解析从 librbd API 到 OSD 的读写请求的转换过程。</li></ul></li><li><p><strong>数据组织：</strong></p><ul><li>RBD 将块设备视为从字节零开始的扁平文件，并通过 librbd 将请求分解为更小的对象存储在 Ceph 集群中。</li><li>默认使用 4MB 大小的固定对象进行存储。</li></ul></li><li><p><strong>API 接口：</strong></p><ul><li>librbd 是一个用户空间库，提供 C、C++ 和 Python 绑定。</li><li>常见集成包括 QEMU，它通过 librbd 与 RBD 交互。</li><li>API 提供同步和异步的读写、刷新和丢弃操作。</li></ul></li><li><p><strong>内部实现：</strong></p><ul><li>API 方法在 <code>librbd.cc</code> 文件中定义，负责维护 API 的稳定性和 ABI。</li><li>内部将同步调用转换为异步调用，并通过异步完成回调处理。</li><li>I/O 请求首先被转换为图像范围的 I/O，然后进一步分解为对象范围的 I/O。</li></ul></li><li><p><strong>I/O 分发层：</strong></p><ul><li>I/O 分发层包括多个子组件，如排队层、服务质量层、独占锁层等。</li><li>核心层负责将 I/O 请求发送到 Ceph OSD 集群。</li></ul></li><li><p><strong>对象 I/O 分发：</strong></p><ul><li>对象 I/O 分发层处理具体的对象读写请求。</li><li>包括缓存层、加密层、日志层等，最终通过核心层将请求发送到 OSD。</li></ul></li><li><p><strong>测试与未来计划：</strong></p><ul><li>有大量的单元测试代码，确保每个组件的正确性。</li><li>未来将安排更多会议深入探讨这些细节。</li></ul></li></ol><p><strong>后续行动计划：</strong></p><ul><li>安排更多会议以深入讨论 RBD 的 I/O 路径和其他相关主题。</li><li>参与者可以通过邮件列表等方式与 Jason Dillman 联系，提出问题或建议。</li></ul><p><strong>备注：</strong></p><ul><li>由于时间限制，会议未能覆盖所有细节，未来会议将继续探讨。</li></ul>',9)])])}const u=i(_,[["render",r]]);export{h as __pageData,u as default};
